  // Price Calculation Utility (Net + % or Fixed Commission -> Public Price)
  function calculatePublicPrice(netPrice, commType, commValue) {
    const net = Number(netPrice || 0);
    const val = Number(commValue || 0);
    if (net <= 0) return { net: 0, gain: 0, publicPrice: 0 };
    const gain = commType === 'FIXED' ? val : (net * (val / 100));
    const pub = Math.round((net + gain) * 100) / 100;
    return {
      net: Math.round(net * 100) / 100,
      gain: Math.round(gain * 100) / 100,
      publicPrice: pub
    };
  }

  // Currency Conversion Engine (EUR=1, USD=1.08, AED=3.97)
  const FX_FROM_EUR = { EUR: 1, USD: 1.08, AED: 3.97 };
  function convertCurrency(amount, fromCurr, toCurr) {
    const n = Number(amount || 0);
    if (n <= 0) return 0;
    const fc = FX_FROM_EUR[fromCurr] ? fromCurr : 'EUR';
    const tc = FX_FROM_EUR[toCurr] ? toCurr : 'EUR';
    if (fc === tc) return n;
    const inEur = n / FX_FROM_EUR[fc];
    return inEur * FX_FROM_EUR[tc];
  }

  function formatItemPublicPrice(item, displayCurrency) {
    if (item.price_on_request) {
      return item.price_label || ((item.tab === 'VEHICLES' || item.tab === 'YACHTS') ? 'A cotizar con el cliente' : 'Cotizar por Lote');
    }
    const baseCurr = item.base_currency || 'EUR';
    const baseVal = Number(item.public_price || item.price_eur || 0);
    if (baseVal <= 0) {
      return item.price_label || 'Cotizar por Lote';
    }
    const converted = convertCurrency(baseVal, baseCurr, displayCurrency);
    const rounded = converted >= 100 ? Math.round(converted) : Math.round(converted * 100) / 100;
    const numStr = rounded.toLocaleString('es-ES', { maximumFractionDigits: rounded >= 100 ? 0 : 2 });
    let priceText = '';
    if (displayCurrency === 'EUR') priceText = numStr + ' €';
    else if (displayCurrency === 'USD') priceText = '$' + numStr + ' USD';
    else priceText = numStr + ' AED';
    return item.unit_label ? (priceText + ' ' + item.unit_label) : priceText;
  }

